/* ESTILO PERSONALIZADO: BARRA DE PESQUISA GOURMET
   Engenheiro responsável: Softload 
*/

.search-wrapper {
  max-width: 350px;
  width: 100%;
  margin-left: auto;
}

/* Resetando a tabela nativa do Blogger */
.search-wrapper table.gsc-search-box {
  border-collapse: collapse;
  border-style: none;
  margin-bottom: 0;
  width: 100%;
}

.search-wrapper td.gsc-input {
  padding-right: 0 !important;
}

.search-wrapper td.gsc-search-button {
  vertical-align: middle;
}

/* Container do Input */
.search-wrapper input.gsc-input {
  background: #fdfbfb !important; /* Branco Creme */
  border: 2px solid #e0e0e0 !important;
  border-right: none !important;
  border-radius: 50px 0 0 50px !important;
  padding: 10px 20px !important;
  font-size: 14px !important;
  color: #555 !important;
  outline: none !important;
  transition: all 0.3s ease;
  width: 100% !important;
  height: 45px !important;
  box-sizing: border-box !important;
}

/* Foco no Input */
.search-wrapper input.gsc-input:focus {
  border-color: #6f42c1 !important; /* Roxo principal */
  box-shadow: 0 0 8px rgba(111, 66, 193, 0.1);
  background: #fff !important;
}

/* Estilização do Botão */
.search-wrapper input.gsc-search-button {
  background: linear-gradient(45deg, #6f42c1, #d63384) !important; /* Roxo para Rosa */
  border: none !important;
  color: #ffffff !important;
  border-radius: 0 50px 50px 0 !important;
  padding: 0 20px !important;
  height: 45px !important;
  font-weight: 600 !important;
  text-transform: uppercase;
  font-size: 12px !important;
  cursor: pointer;
  transition: opacity 0.3s ease;
  margin-left: -1px; /* Ajuste para colar no input */
}

.search-wrapper input.gsc-search-button:hover {
  opacity: 0.9;
  box-shadow: -2px 0 10px rgba(214, 51, 132, 0.2);
}

/* Esconder o título padrão do widget para manter a Nav limpa */
.search-wrapper h2.title {
  display: none;
}

/* Responsividade Mobile */
@media (max-width: 991px) {
  .search-wrapper {
    max-width: 100%;
    margin: 15px 0;
  }
}

.post-thumb-img {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9; /* Garante a proporção visual no navegador */
  object-fit: cover;    /* Evita que a imagem fique esticada */
  border-radius: 12px;  /* Mantém o estilo Gourmet */
}

/* CSS obrigatório para o efeito funcionar */
.btn, .nav-link, .dropdown-item { 
  position: relative !important; 
  overflow: hidden !important; 
}

.ripple-effect {
  position: absolute;
  background: rgba(255, 255, 255, 0.4);
  transform: translate(-50%, -50%);
  pointer-events: none;
  border-radius: 50%;
  animation: ripple-animation 0.6s linear;
}

@keyframes ripple-animation {
  from { width: 0px; height: 0px; opacity: 0.5; }
  to { width: 500px; height: 500px; opacity: 0; }
}

