body.script:
//
document.addEventListener('DOMContentLoaded', () => {
  'use strict';

  /* --- DARK MODE --- */
  const getStoredTheme = () => localStorage.getItem('theme');
  const setStoredTheme = theme => localStorage.setItem('theme', theme);
  const getPreferredTheme = () => {
    const storedTheme = getStoredTheme();
    if (storedTheme) return storedTheme;
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  };

  const setTheme = theme => {
    document.documentElement.setAttribute('data-bs-theme', theme);
    atualizarIcone(theme);
  };

  const atualizarIcone = (theme) => {
    const btnIcone = document.querySelector('.btn-dark-mode i');
    if (btnIcone) {
      btnIcone.className = theme === 'dark' ? 'bi bi-sun-fill text-warning' : 'bi bi-moon-stars-fill text-dark';
    }
  };

  setTheme(getPreferredTheme());

  window.alternarTema = () => {
    const temaAtual = document.documentElement.getAttribute('data-bs-theme');
    const novoTema = temaAtual === 'dark' ? 'light' : 'dark';
    setStoredTheme(novoTema);
    setTheme(novoTema);
  };

  const toggleBtns = document.querySelectorAll('.btn-dark-mode');
  toggleBtns.forEach(btn => {
    btn.addEventListener('click', window.alternarTema);
  });

  /* --- ANIMAÇÕES DE SCROLL --- */
  const observerOptions = { root: null, rootMargin: '0px', threshold: 0 };
  const scrollObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target); 
      }
    });
  }, observerOptions);

  const elementosAnimaveis = document.querySelectorAll('.card, aside .widget, .animate-up');
  elementosAnimaveis.forEach((el, index) => {
    el.classList.add('animate-up');
    el.style.transitionDelay = `${(index % 3) * 0.1}s`; 
    scrollObserver.observe(el);
  });

  /* --- SCROLL TO TOP --- */
  const btnScroll = document.getElementById('btnScrollToTop');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 300) {
      btnScroll.classList.add('show');
    } else {
      btnScroll.classList.remove('show');
    }
  });

  btnScroll.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

});
//


//
document.addEventListener('DOMContentLoaded', () => {
  const searchInput = document.querySelector('.search-input-custom');

  // Limpa o input ao pressionar ESC
  searchInput?.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      searchInput.value = '';
      searchInput.blur();
    }
  });
});
//

//
/* * BOUTIQUE GOURMET - RESIZE 16:9 ENGINE (Vanilla JS)
 * Engenheiro: Softload | Foco: Alta Performance
 */
(function() {
  // === CONFIGURAÇÃO ===
  const CONFIG = {
    width: 800,  // Largura (Resolução HD)
    height: 450, // Altura (Cálculo perfeito de 16:9)
    // Insira as classes das imagens que devem ser redimensionadas separadas por vírgula
    selectors: '.post-thumb img, .popular-posts img, .card-img-top' 
  };

  const processImages16by9 = () => {
    const images = document.querySelectorAll(CONFIG.selectors);

    images.forEach(img => {
      let src = img.getAttribute('src');
      if (!src) return;

      // Verifica se a imagem está hospedada no Google/Blogger
      if (src.includes('bp.blogspot.com') || src.includes('googleusercontent.com')) {

        // Expressão Regular Sênior: Substitui qualquer tamanho prévio pelo 16:9 exato
        let hdUrl = src.replace(/\/(s|w|h)\d+(-[a-z]+)?\//g, `/w${CONFIG.width}-h${CONFIG.height}-p-k-no-nu/`)
                       .replace(/=(s|w|h)\d+(-[a-z]+)?/g, `=w${CONFIG.width}-h${CONFIG.height}-p-k-no-nu`);

        // Aplica a nova URL apenas se for diferente, economizando CPU
        if (img.src !== hdUrl) {
          img.src = hdUrl;
        }
      }
    });
  };

  // Dispara o script assim que o esqueleto do HTML estiver pronto, mas antes de baixar todas as mídias
  window.addEventListener('DOMContentLoaded', processImages16by9);
})();


// Ripple Effect Bare-Metal
document.querySelectorAll('.btn, .nav-link').forEach(button => {
  button.addEventListener('click', function(e) {
    let x = e.clientX - e.target.getBoundingClientRect().left;
    let y = e.clientY - e.target.getBoundingClientRect().top;

    let ripple = document.createElement('span');
    ripple.style.left = x + 'px';
    ripple.style.top = y + 'px';
    ripple.classList.add('ripple-effect');

    this.appendChild(ripple);

    setTimeout(() => { ripple.remove(); }, 600);
  });
});

